code.python:
def trailing_average(readings: list[float], window: int) -> list[float]:
    averages = []
    total = 0.0
    for i, x in enumerate(readings):
        total += x
        if i >= window:
            # The reading that just slid out of the window.
            total -= readings[i - window]
        averages.append(total / min(i + 1, window))
    return averages

