fn trailing_average(readings: Vec<f64>, window: usize) -> Vec<f64> {
    let mut averages = Vec::with_capacity(readings.len());
    let mut total = 0.0;
    for i in 0..readings.len() {
        total += readings[i];
        if i >= window {
            // The reading that just slid out of the window.
            total -= readings[i - window];
        }
        averages.push(total / (i + 1).min(window) as f64);
    }
    averages
}
